import {explorationExamples} from './exploration-examples.js';
import {isDegreeOffer} from './coverage-050-review.js';
import {escapeHTML as h} from './html.js';
const covers=top=>top.some(p=>p.sustains===true),unknown=top=>top.some(p=>p.sustains===null),names=top=>top.map(p=>h(p.title)).join(' · ')||'None';
export function coverageChangeTable(rows,labels){
 const eligible=rows.filter(m=>m.coverageReview);if(!eligible.length)return '<p>A frozen 0.49 baseline is unavailable for this selection.</p>';
 const groups=Object.keys(labels).map(phase=>({phase,rows:eligible.filter(m=>m.phase===phase)})).filter(g=>g.rows.length);
 groups.unshift({phase:'all',rows:eligible});
 const pair=(rs,p)=>rs.filter(m=>p(m.coverageReview.before.top)).length+' → '+rs.filter(m=>p(m.top)).length;
 return '<p>Frozen 0.49 → current. The current list also includes later 0.52 follow-up answers. Each row keeps its own cohort denominator. Original holdout and fresh holdout are reported separately; paired diagnostics enter only when selected. Wage proxies are estimates, not job offers. Private models without a stored 0.49 baseline are excluded from this comparison.</p><div class="table-scroll" tabindex="0"><table class="coverage-change-table"><thead><tr><th>Cohort</th><th>Models</th><th>Has Top</th><th>Has college / graduate Top</th><th>Any Top covers<br>before → pay evidence only → current</th><th>First-ranked covers</th><th>Unknown pay in Top</th></tr></thead><tbody>'+groups.map(({phase,rows:rs})=>'<tr><th>'+h(phase==='all'?'Selection total':labels[phase])+'</th><td>'+rs.length+'</td><td>'+pair(rs,t=>!!t.length)+'</td><td>'+pair(rs,t=>t.some(isDegreeOffer))+'</td><td>'+rs.filter(m=>covers(m.coverageReview.before.top)).length+' → '+rs.filter(m=>covers(m.coverageReview.payOnlyTop)).length+' → '+rs.filter(m=>covers(m.top)).length+'</td><td>'+pair(rs,t=>t[0]?.sustains===true)+'</td><td>'+pair(rs,unknown)+'</td></tr>').join('')+'</tbody></table></div><p>“Pay evidence only” keeps each model’s frozen Top list and applies the new wage references. Current results also apply comparable-fit ranking and later separately recorded exploration and follow-up reflections. Opportunity counts are not measured student outcomes.</p>';
}
export function coverageReason(m){
 if(!m.top.length)return 'No confirmed Top yet · clarify interests through exploration.';
 if(covers(m.top))return 'A Top option covers this budget under the stated pay assumptions.';
 if(unknown(m.top))return 'Top affordability remains partly unknown · inspect wage scope and first paid stage.';
 return 'Assessed Top starting-pay references fall below this lifestyle budget.';
}
export function coverageReviewTrail(m){
 const r=m.coverageReview;if(!r)return '';
 return '<section class="coverage-release"><h3>Cumulative coverage change · 0.49 → current</h3><p>The current list includes the later 0.52 follow-up answers; this is not a pay-only comparison.</p><p>'+h(coverageReason(m))+'</p><p><strong>Before:</strong> '+names(r.before.top)+'</p>'+r.before.top.map(p=>'<details id="evidence-before050-'+h(p.id)+'"><summary>'+h(p.title)+' · frozen 0.49</summary><p>Annual first-stage reference: '+(Number.isFinite(p.firstPay)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(p.firstPay):'Not assessed')+'. Lifestyle: '+(p.sustains===true?'covered':p.sustains===false?'below budget':'unknown')+'.</p><p>Retained historical offer. Current evidence is shown separately below.</p></details>').join('')+'<p><strong>Current:</strong> '+names(m.top)+'</p><p>Added: '+names(r.added)+'. Left Top: '+names(r.removed)+'.</p><p>'+h(r.reason)+'</p>'+(r.exploration?'<h4>New exploration reflections</h4><p>Anonymous examples and biography-based answers were frozen before the final replay. These are simulations, not student responses. Earlier answers remain in the original histories.</p>'+r.exploration.answers.map(a=>{const e=explorationExamples[a.questionId];return '<details><summary>'+h(a.response)+' · '+h(a.confidence)+' confidence</summary>'+(e?'<p>'+h(e.scene)+'</p><p><strong>Try it:</strong> '+h(e.tryIt)+'</p><p>'+h(e.reflection)+'</p>':'')+'<p><strong>Underlying interest:</strong> '+h(a.originalPrompt)+'</p><p>'+h(a.evidence)+'</p></details>';}).join(''):'<p>No new exploration response was inferred for this model. Its current result reuses the existing frozen reflections.</p>')+'</section>';
}
